import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

const TOTAL = 8;

async function counterText(page: Page) {
  const body = await page.locator('body').innerText();
  return (body.match(/\d+ מתוך \d+/) ?? [''])[0];
}

test.describe('Режим молитвы «יחיד / מניין»', () => {
  test('PM-03 Смена режима посреди молитвы не сбрасывает позицию #6a86f7e7 @prod-safe @mobile', async ({ page }) => {
    const consoleErrors: string[] = [];
    page.on('console', (msg) => {
      if (msg.type() === 'error') consoleErrors.push(msg.text());
    });

    const yachid = page.getByRole('radio', { name: 'יחיד' });
    const minyan = page.getByRole('radio', { name: 'מניין' });

    // 1. Открыть `/prayer/mincha_ashkenaz`; нажимать «קודם», пока не будет «1 מתוך 8».
    await page.goto('/prayer/mincha_ashkenaz');
    await expect(page.getByText(/\d+ מתוך \d+/).first()).toBeVisible();
    const prev = page.getByText('קודם', { exact: true });
    for (let i = 0; i < TOTAL + 5; i++) {
      if ((await counterText(page)) === `1 מתוך ${TOTAL}`) break;
      await prev.click();
    }
    await expect(page.getByText(`1 מתוך ${TOTAL}`).first()).toBeVisible();

    // 2. Нажать «המשך» 3 раза → «4 מתוך 8»; запомнить заголовок и текст секции.
    const next = page.getByText('המשך', { exact: true });
    for (let i = 2; i <= 4; i++) {
      await next.click();
      await expect(page.getByText(`${i} מתוך ${TOTAL}`).first()).toBeVisible();
    }
    const textBefore = await page.locator('body').innerText();

    // 3. Нажать «מניין», затем «יחיד».
    await minyan.click();
    await expect(minyan).toHaveAttribute('aria-checked', 'true');
    await yachid.click();
    await expect(yachid).toHaveAttribute('aria-checked', 'true');
    // Счётчик, заголовок и текст не изменились
    await expect(page.getByText(`4 מתוך ${TOTAL}`).first()).toBeVisible();
    expect(await page.locator('body').innerText()).toBe(textBefore);

    // 4. Переключить режим 8 раз подряд («מניין»/«יחיד» поочерёдно), дожидаясь aria-checked после каждого нажатия.
    for (let i = 0; i < 8; i++) {
      const target = i % 2 === 0 ? minyan : yachid;
      const other = i % 2 === 0 ? yachid : minyan;
      await target.click();
      await expect(target).toHaveAttribute('aria-checked', 'true');
      await expect(other).toHaveAttribute('aria-checked', 'false');
    }
    await expect(page.getByText(`4 מתוך ${TOTAL}`).first()).toBeVisible();
    expect(await page.locator('body').innerText()).toBe(textBefore);

    // Ошибок в консоли нет
    expect(consoleErrors).toEqual([]);

    // Вернуть режим «יחיד»
    await yachid.click();
    await expect(yachid).toHaveAttribute('aria-checked', 'true');
  });
});
